css:
.scoutsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1a2330;
    background: radial-gradient(1200px 480px at 80% -10%, #eef2ff 0%, rgba(238,242,255,0) 60%), linear-gradient(170deg, #f7f8fb 0%, #eef1f6 100%);
    border-radius: 18px;
}

.scoutsim-container * {
    box-sizing: border-box;
}

.scoutsim-header {
    text-align: center;
    padding: 30px 22px 26px;
    background: linear-gradient(135deg, #1b1140 0%, #2a1d63 45%, #0f5d7a 100%);
    color: #f4f6ff;
    border-radius: 16px;
    margin-bottom: 18px;
    box-shadow: 0 16px 38px rgba(27, 17, 64, 0.32);
}

.scoutsim-header h1 {
    margin: 12px 0 10px;
    font-size: 2.5rem;
    font-weight: 800;
    letter-spacing: -0.6px;
    color: #ffffff;
}

.scoutsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #8ff0d8;
    background: rgba(143, 240, 216, 0.12);
    border: 1px solid rgba(143, 240, 216, 0.40);
    padding: 5px 14px;
    border-radius: 999px;
}

.scoutsim-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.58;
    color: #d2d8f5;
}

.scoutsim-opps {
    display: flex;
    align-items: stretch;
    gap: 12px;
    margin-bottom: 18px;
}

.scoutsim-opp {
    flex: 1;
    background: #ffffff;
    border-radius: 14px;
    padding: 14px 16px;
    box-shadow: 0 5px 16px rgba(26, 35, 48, 0.08);
    display: flex;
    flex-direction: column;
    gap: 4px;
    border-top: 4px solid #6c5ce0;
}

.scoutsim-opp-a { border-top-color: #2f80ed; }
.scoutsim-opp-b { border-top-color: #16a085; }
.scoutsim-opp-c { border-top-color: #c0392b; }

.scoutsim-opp-tag {
    font-size: 0.68rem;
    text-transform: uppercase;
    letter-spacing: 0.8px;
    font-weight: 800;
    color: #8a93a6;
}

.scoutsim-opp-name {
    font-weight: 800;
    font-size: 1.04rem;
    color: #1b1140;
}

.scoutsim-opp-a .scoutsim-opp-name { color: #2f80ed; }
.scoutsim-opp-b .scoutsim-opp-name { color: #119a80; }
.scoutsim-opp-c .scoutsim-opp-name { color: #c0392b; }

.scoutsim-opp-meta {
    font-size: 0.79rem;
    color: #5d6678;
    line-height: 1.4;
}

.scoutsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #46506a;
    margin-bottom: 16px;
    padding: 4px;
}

.scoutsim-period-counter #currentDay,
.scoutsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #6c5ce0;
}

.scoutsim-round-name {
    background: rgba(108, 92, 224, 0.13);
    color: #5a48c4;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.scoutsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #0e6f6f;
    background: rgba(22, 160, 133, 0.13);
    border: 1px solid rgba(22, 160, 133, 0.30);
    padding: 4px 12px;
    border-radius: 999px;
}

.scoutsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.scoutsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    box-shadow: 0 6px 16px rgba(26, 35, 48, 0.08);
    border-top: 4px solid #6c5ce0;
}

.scoutsim-card-runway { border-top-color: #1b1140; }
.scoutsim-card-cash { border-top-color: #0f5d7a; }
.scoutsim-card-evidence { border-top-color: #16a085; }
.scoutsim-card-fit { border-top-color: #6c5ce0; }

.scoutsim-label {
    font-size: 0.73rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6c7689;
}

.scoutsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #1b1140;
    font-variant-numeric: tabular-nums;
}

.scoutsim-card-runway .scoutsim-value { color: #1b1140; }
.scoutsim-card-cash .scoutsim-value { color: #0f5d7a; }
.scoutsim-card-evidence .scoutsim-value { color: #119a80; }
.scoutsim-card-fit .scoutsim-value { color: #6c5ce0; }

.scoutsim-sublabel {
    font-size: 0.76rem;
    color: #7a8398;
    line-height: 1.35;
}

/* Runway danger / safe states (runway is the headline constraint). */
.scoutsim-card-runway.scoutsim-runway-danger { border-top-color: #d64545; }
.scoutsim-card-runway.scoutsim-runway-danger .scoutsim-value { color: #d64545; }
.scoutsim-card-runway.scoutsim-runway-warn { border-top-color: #e08a1e; }
.scoutsim-card-runway.scoutsim-runway-warn .scoutsim-value { color: #c8780f; }
.scoutsim-card-runway.scoutsim-runway-good { border-top-color: #16a085; }
.scoutsim-card-runway.scoutsim-runway-good .scoutsim-value { color: #119a80; }

.scoutsim-card-evidence.scoutsim-evidence-good { border-top-color: #16a085; }
.scoutsim-card-evidence.scoutsim-evidence-good .scoutsim-value { color: #119a80; }
.scoutsim-card-evidence.scoutsim-evidence-weak { border-top-color: #d64545; }
.scoutsim-card-evidence.scoutsim-evidence-weak .scoutsim-value { color: #d64545; }

.scoutsim-card-fit.scoutsim-fit-good { border-top-color: #16a085; }
.scoutsim-card-fit.scoutsim-fit-good .scoutsim-value { color: #119a80; }
.scoutsim-card-fit.scoutsim-fit-weak { border-top-color: #d64545; }
.scoutsim-card-fit.scoutsim-fit-weak .scoutsim-value { color: #d64545; }

.scoutsim-resource-bar {
    display: flex;
    flex-wrap: wrap;
    gap: 10px 26px;
    align-items: center;
    background: #ffffff;
    border: 1px solid #e3e7f0;
    color: #46506a;
    padding: 11px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.9rem;
}

.scoutsim-resource-item {
    display: inline-flex;
    gap: 8px;
    align-items: baseline;
}

.scoutsim-resource-key {
    color: #6c7689;
    font-weight: 600;
}

.scoutsim-resource-item span:last-child {
    color: #6c5ce0;
    font-weight: 800;
    font-variant-numeric: tabular-nums;
}

.scoutsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #6c5ce0;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(26, 35, 48, 0.07);
}

.scoutsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.scoutsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #1b1140;
    margin-bottom: 6px;
}

.scoutsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.58;
    color: #3a455a;
}

.scoutsim-briefing-text strong { color: #5a48c4; }
.scoutsim-briefing-text em { color: #119a80; font-style: italic; }

.scoutsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(26, 35, 48, 0.07);
}

.scoutsim-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #1b1140;
    border-bottom: 2px solid #ebedf4;
    padding-bottom: 8px;
}

.scoutsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2a3550;
    margin: 14px 0 6px;
    line-height: 1.45;
}

.scoutsim-container select,
.scoutsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #ccd3e0;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #ffffff;
    color: #1a2330;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.scoutsim-container select:focus,
.scoutsim-container input[type="number"]:focus {
    outline: none;
    border-color: #6c5ce0;
    box-shadow: 0 0 0 3px rgba(108, 92, 224, 0.16);
}

.scoutsim-container select option {
    background-color: #ffffff;
    color: #1a2330;
}

.scoutsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #6c5ce0;
}

.scoutsim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #46506a;
    margin-top: 4px;
}

.scoutsim-range-readout span:nth-child(2) {
    color: #6c5ce0;
    font-weight: 800;
}

.scoutsim-hint {
    font-size: 0.8rem;
    color: #7a8398;
    margin-top: 6px;
    line-height: 1.4;
    font-style: italic;
}

.scoutsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.scoutsim-container .btn-primary {
    background: linear-gradient(135deg, #5a48c4 0%, #6c5ce0 55%, #0f5d7a 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(90, 72, 196, 0.32);
}

.scoutsim-container .btn-primary:hover {
    filter: brightness(1.07);
}

.scoutsim-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #ccd3e0;
    color: #5d6678;
    background: transparent;
}

.scoutsim-coach {
    background: linear-gradient(160deg, #1b1140 0%, #241753 100%);
    color: #e6e9ff;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(27, 17, 64, 0.26);
}

.scoutsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #8ff0d8;
    margin-bottom: 8px;
}

.scoutsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.58;
}

.scoutsim-coach-body strong { color: #a8f5e3; }
.scoutsim-coach-body em { color: #ffd79a; font-style: italic; }

.scoutsim-history,
.scoutsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(26, 35, 48, 0.07);
}

.scoutsim-history h3,
.scoutsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #1b1140;
}

.scoutsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #3a455a;
}

.scoutsim-container table#usfHistoryTable th {
    background: #f0ecfb;
    color: #5a48c4;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #ded5f4;
}

.scoutsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef0f5;
    color: #3a455a;
}

.scoutsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf9fe;
}

.scoutsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .scoutsim-container {
        padding: 14px;
    }
    .scoutsim-header h1 {
        font-size: 1.8rem;
    }
    .scoutsim-opps {
        flex-direction: column;
    }
    .scoutsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .scoutsim-value {
        font-size: 2rem;
    }
    .scoutsim-clock {
        margin-left: 0;
    }
    .scoutsim-period-counter {
        font-size: 0.88rem;
    }
    .scoutsim-resource-bar {
        flex-direction: column;
        align-items: flex-start;
        gap: 6px;
    }
    .scoutsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ===== v1.1.0 completion debrief (append-only, scoutsim-cm-*) ===== */
.scoutsim-cm { color: #1e2f31; font-family: inherit; }
.scoutsim-cm-generic { font-size: 15px; text-align: center; }
.scoutsim-cm-scoreband { text-align: center; padding: 6px 0 14px; border-bottom: 1px solid rgba(30,47,49,0.12); margin-bottom: 16px; }
.scoutsim-cm-score { font-size: 46px; font-weight: 700; line-height: 1; color: #2f7d7d; }
.scoutsim-cm-score-max { font-size: 20px; font-weight: 500; color: #778787; margin-left: 2px; }
.scoutsim-cm-tier { font-size: 20px; font-weight: 600; margin-top: 6px; color: #1e2f31; }
.scoutsim-cm-caption { font-size: 11.5px; letter-spacing: .05em; text-transform: uppercase; color: #778787; margin-top: 4px; }
.scoutsim-cm-kpis { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin-bottom: 14px; }
.scoutsim-cm-kpi { flex: 1 1 92px; min-width: 92px; background: rgba(47,125,125,0.08); border: 1px solid rgba(47,125,125,0.2); border-radius: 10px; padding: 10px 8px; text-align: center; }
.scoutsim-cm-kpi-val { display: block; font-size: 20px; font-weight: 700; color: #1e2f31; }
.scoutsim-cm-kpi-lbl { display: block; font-size: 11px; margin-top: 3px; color: #52605f; }
.scoutsim-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; justify-content: center; margin-bottom: 14px; }
.scoutsim-cm-chip { font-size: 12.5px; font-weight: 600; padding: 5px 11px; border-radius: 999px; border: 1px solid transparent; }
.scoutsim-cm-chip.is-met { background: rgba(46,143,107,0.14); border-color: rgba(46,143,107,0.42); color: #1f6e50; }
.scoutsim-cm-chip.is-missed { background: rgba(197,74,74,0.12); border-color: rgba(197,74,74,0.4); color: #a23b3b; }
.scoutsim-cm-insights { margin: 0; padding-left: 18px; }
.scoutsim-cm-insights li { font-size: 13.5px; line-height: 1.5; color: #32423f; margin-bottom: 7px; }

