(function() {
    'use strict';

    class OpportunityScoutAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Opportunity Scout`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // --- Numbers reference card (Helveti Labs GmbH) ---
            this.START_CASH = 118000;     // CHF on day one
            this.MONTHLY_BURN = 22000;    // 2 salaries + cloud + desk
            this.WEEKLY_BURN = 5500;      // 22,000 / 4
            this.START_CREDITS = 40;      // interview credits
            this.START_BUDGET = 12000;    // experiment budget (CHF)
            this.GRANT_TRANCHE = 60000;   // frozen second tranche
            this.SAFE_OFFER = 250000;     // angel SAFE in R4
            this.EVIDENCE_TRANCHE_GATE = 55; // grant agency accepts validated demand at >= 55
            this.FIT_ANGEL_GATE = 65;     // angel requires fit >= 65
            this.EVIDENCE_ANGEL_GATE = 60;// angel requires real validation signal >= 60
            this.CREDIT_PRICE = 250;      // CHF per extra interview credit

            // Rubric truth: FairShip (B) is the rubric's top score under runway;
            // AlpTrace (C) is the exciting-but-third "passion" trap.
            this.RUBRIC_FIRST = `b`;
            this.PASSION_OPP = `c`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: this.START_CASH,           // CHF in bank
                    runway: Math.round((this.START_CASH / this.MONTHLY_BURN) * 10) / 10, // months
                    evidence: 0,                     // validation evidence (0-100)
                    fit: 0,                          // opportunity-fit score of committed opp (0-100)
                    credits: this.START_CREDITS,     // interview credits remaining
                    budget: this.START_BUDGET,       // experiment budget remaining (CHF)
                    committed: ``,                   // committed opportunity code: a/b/c or ''
                    // Sticky run-defining penalty flags (gate the top verdict).
                    parallelTrap: false,             // spread scarce validation across all three
                    passionTrap: false,              // chose excitement (C) over the rubric
                    vanityTrap: false,               // treated free signups as proof of demand
                    pivotDenial: false,              // persevered on contradicted FairShip evidence
                    trancheLost: false,              // evidence too thin -> CHF 60,000 tranche lost
                    delayMonths: 0,                  // months of runway burned by indecision
                    safeSecured: false,              // angel SAFE landed in R4
                    // History arrays for the chart.
                    runwayHistory: [Math.round((this.START_CASH / this.MONTHLY_BURN) * 10) / 10],
                    evidenceHistory: [0],
                    fitHistory: [0],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the classic errors — a blind
                // click-through must NOT auto-win (passion + parallel + vanity + denial + delay).
                state.decisions = {
                    rank: `c`,
                    carry: `all`,
                    kill: `none`,
                    disc: 40,
                    focus: `spread`,
                    tactic: `signups`,
                    read: `vanity`,
                    spend: `0`,
                    decision: `persevere`,
                    falsify: `none`,
                    speed: `month`,
                    extra: `0`,
                    thesis: `story`,
                    ask: `vanity`,
                    probe: `deflect`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const rk = document.getElementById(`rankInput`);
                const ca = document.getElementById(`carryInput`);
                const ki = document.getElementById(`killInput`);
                const di = document.getElementById(`discInput`);
                if (rk) decisions.rank = rk.value;
                if (ca) decisions.carry = ca.value;
                if (ki) decisions.kill = ki.value;
                if (di) decisions.disc = parseInt(di.value, 10);
                if (!Number.isFinite(decisions.disc) || decisions.disc < 0 || decisions.disc > 100) {
                    warn(`warn_disc_range`); return false;
                }
            } else if (round === 2) {
                const fo = document.getElementById(`focusInput`);
                const ta = document.getElementById(`tacticInput`);
                const re = document.getElementById(`readInput`);
                const sp = document.getElementById(`spendInput`);
                if (fo) decisions.focus = fo.value;
                if (ta) decisions.tactic = ta.value;
                if (re) decisions.read = re.value;
                if (sp) decisions.spend = sp.value;
                const spendVal = parseFloat(decisions.spend);
                if (!Number.isFinite(spendVal) || spendVal < 0 || spendVal > state.domainState.budget) {
                    warn(`warn_spend_budget`); return false;
                }
            } else if (round === 3) {
                const de = document.getElementById(`decisionInput`);
                const fa = document.getElementById(`falsifyInput`);
                const sd = document.getElementById(`speedInput`);
                const ex = document.getElementById(`extraInput`);
                if (de) decisions.decision = de.value;
                if (fa) decisions.falsify = fa.value;
                if (sd) decisions.speed = sd.value;
                if (ex) decisions.extra = ex.value;
                const extraCredits = parseInt(decisions.extra, 10);
                if (!Number.isFinite(extraCredits) || extraCredits < 0) {
                    warn(`warn_extra_value`); return false;
                }
                if (extraCredits * this.CREDIT_PRICE > state.domainState.cash) {
                    warn(`warn_extra_cash`); return false;
                }
            } else if (round === 4) {
                const th = document.getElementById(`thesisInput`);
                const ak = document.getElementById(`askInput`);
                const pr = document.getElementById(`probeInput`);
                const cv = document.getElementById(`convictionInput`);
                if (th) decisions.thesis = th.value;
                if (ak) decisions.ask = ak.value;
                if (pr) decisions.probe = pr.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            this._updateBriefing(state);
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let evidenceDelta = 0, fitDelta = 0;
            let spendThisRound = 0;          // CHF experiment / extra-data spend
            let delayBurn = 0;               // CHF of indecision burn
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // --- Screen the three opportunities. Set the committed lead. ---
                const trustRubric = d.disc >= 55;

                // The committed lead is the ranked first choice; chasing C against the
                // rubric (which favours B) is the "passion over score" trap.
                ds.committed = d.rank;

                if (d.rank === this.RUBRIC_FIRST) {
                    fitDelta += 24; coachKey = `coach_r1_rubric`;
                } else if (d.rank === `a`) {
                    fitDelta += 10; coachKey = `coach_r1_swisscare`;   // big market, but the cycle outlives the runway
                } else if (d.rank === this.PASSION_OPP) {
                    fitDelta += 6;
                    ds.passionTrap = true;                            // chose excitement over the score
                    coachKey = `coach_r1_passion`;
                }

                // Kill discipline: concentrating credits requires killing options.
                if (d.carry === `all` || d.kill === `none`) {
                    ds.parallelTrap = true;                           // cannot falsify anything on 13 credits each
                    fitDelta -= 6;
                    coachKey = `coach_r1_parallel`;
                } else if (d.carry === `two` && d.kill === `c`) {
                    fitDelta += 8;                                    // killed the slow niche, kept live contenders
                    if (d.rank === this.RUBRIC_FIRST) coachKey = `coach_r1_sharp`;
                } else if (d.carry === `one`) {
                    fitDelta += 5;                                    // maximum focus, slightly risky this early
                }

                // Trusting the rubric over gut buys fit clarity.
                if (trustRubric && d.rank === this.RUBRIC_FIRST) fitDelta += 6;
                else if (d.disc <= 25 && d.rank === this.PASSION_OPP) { fitDelta -= 4; }

                summaryKey = (d.rank === this.RUBRIC_FIRST && d.carry !== `all` && d.kill !== `none`) ? `sum_r1_good` :
                             (ds.passionTrap ? `sum_r1_passion` :
                             (ds.parallelTrap ? `sum_r1_parallel` : `sum_r1_weak`));
            } else if (round === 2) {
                // --- Validate under constraint. ---
                spendThisRound = parseFloat(d.spend) || 0;
                ds.budget = Math.max(0, ds.budget - spendThisRound);

                // Credit concentration: spreading across all three learns nothing decisive.
                if (d.focus === `spread`) {
                    ds.parallelTrap = true;
                    ds.credits = Math.max(0, ds.credits - 39);        // ~13 each, all consumed
                    evidenceDelta -= 6;
                    coachKey = `coach_r2_spread`;
                } else if (d.focus === `two`) {
                    ds.credits = Math.max(0, ds.credits - 40);
                    evidenceDelta += 6;
                } else { // one
                    ds.credits = Math.max(0, ds.credits - 40);
                    evidenceDelta += 12;                              // ~32 on the lead = a real read
                }

                // Validation tactic: only commitment-based tactics produce real signal.
                if (d.tactic === `loi`) {
                    evidenceDelta += 20; fitDelta += 6;
                    coachKey = `coach_r2_loi`;
                } else if (d.tactic === `interviews`) {
                    evidenceDelta += 9;                                // useful, but no commitment asked
                } else { // signups
                    evidenceDelta += 4;                                // a smoke test alone is shallow
                    coachKey = `coach_r2_signups`;
                }

                // Reading signal vs noise: the heart of the round.
                if (d.read === `vanity`) {
                    ds.vanityTrap = true;
                    evidenceDelta -= 12;                               // counting free signups as proof
                    coachKey = `coach_r2_vanity`;
                } else if (d.read === `honest`) {
                    evidenceDelta += 14; fitDelta += 4;
                    if (d.tactic === `loi` && d.focus === `one`) coachKey = `coach_r2_signal`;
                } else { // ignore
                    evidenceDelta -= 6;
                    coachKey = `coach_r2_ignore`;
                }

                // Under-investing: free-only tactics keep evidence too thin to bank.
                if (spendThisRound <= 0) {
                    evidenceDelta -= 8;
                    if (coachKey === `coach_default`) coachKey = `coach_r2_cheap`;
                } else if (spendThisRound >= 8000) {
                    evidenceDelta += 6;                                // a serious experiment that can falsify
                }

                summaryKey = (d.read === `honest` && d.tactic === `loi` && d.focus !== `spread` && spendThisRound > 0) ? `sum_r2_good` :
                             (ds.vanityTrap ? `sum_r2_vanity` :
                             (ds.parallelTrap ? `sum_r2_parallel` : `sum_r2_weak`));
            } else if (round === 3) {
                // --- Decide or pivot. Competitor lands on FairShip; WTP read is CHF 19. ---
                const extraCredits = parseInt(d.extra, 10) || 0;
                spendThisRound = extraCredits * this.CREDIT_PRICE;
                ds.credits += extraCredits;                            // bought more conversations
                if (extraCredits > 0) evidenceDelta += Math.min(10, extraCredits * 0.5);

                // The core entrepreneurial decision against the new evidence.
                if (d.decision === `persevere`) {
                    // FairShip-all-merchants is now contradicted: competitor + WTP gap.
                    if (ds.committed === `b`) {
                        ds.pivotDenial = true;
                        evidenceDelta -= 14; fitDelta -= 16;
                        coachKey = `coach_r3_denial`;
                    } else {
                        evidenceDelta -= 4; fitDelta -= 4;             // persevering on a non-B lead is less catastrophic but still rigid
                        coachKey = `coach_r3_persevere`;
                    }
                } else if (d.decision === `pivot`) {
                    // Pivot one hypothesis: narrow FairShip to cross-border merchants.
                    ds.committed = `b`;
                    fitDelta += 18; evidenceDelta += 10;
                    coachKey = `coach_r3_pivot`;
                } else { // kill -> switch to the evidence-backed opportunity
                    ds.committed = this.RUBRIC_FIRST;
                    fitDelta += 8; evidenceDelta += 4;
                    coachKey = `coach_r3_kill`;
                }

                // Falsification condition: a decision needs a pre-set trigger.
                if (d.falsify === `explicit`) {
                    fitDelta += 8; evidenceDelta += 6;
                } else if (d.falsify === `none`) {
                    fitDelta -= 6;
                    if (coachKey === `coach_default`) coachKey = `coach_r3_nofalsify`;
                }

                // Decision speed: indecision is itself a cost-bearing variable.
                if (d.speed === `now`) {
                    fitDelta += 4;
                } else if (d.speed === `week`) {
                    delayBurn = this.WEEKLY_BURN;                      // -CHF 5,500
                    ds.delayMonths += 0.25;
                } else { // month
                    delayBurn = this.MONTHLY_BURN;                    // a whole month deferring the choice
                    ds.delayMonths += 1;
                    fitDelta -= 4;
                    coachKey = `coach_r3_delay`;
                }

                summaryKey = (d.decision === `pivot` && d.falsify === `explicit` && d.speed !== `month`) ? `sum_r3_good` :
                             (ds.pivotDenial ? `sum_r3_denial` :
                             (d.speed === `month` ? `sum_r3_delay` : `sum_r3_weak`));
            } else if (round === 4) {
                // --- Commit and pitch the angel. ---
                if (d.thesis === `evidence`) {
                    fitDelta += 12; evidenceDelta += 6;
                    coachKey = `coach_r4_evidence`;
                } else if (d.thesis === `hedge`) {
                    ds.parallelTrap = true;                            // a hedged company is not an investable one
                    fitDelta -= 10;
                    coachKey = `coach_r4_hedge`;
                } else { // story
                    fitDelta -= 4;
                    coachKey = `coach_r4_story`;
                }

                if (d.ask === `runway`) {
                    fitDelta += 8;
                } else if (d.ask === `vanity`) {
                    fitDelta -= 6; coachKey = `coach_r4_spend`;
                } else { // none
                    fitDelta -= 3;
                }

                if (d.probe === `own`) {
                    fitDelta += 8; evidenceDelta += 4;
                    if (d.thesis === `evidence`) coachKey = `coach_r4_own`;
                } else if (d.probe === `dismiss`) {
                    fitDelta -= 8; coachKey = `coach_r4_dismiss`;
                } else { // deflect
                    fitDelta -= 4; coachKey = `coach_r4_deflect`;
                }

                if (d.conviction >= 60) fitDelta += 4;
                else if (d.conviction <= 25) fitDelta -= 3;

                summaryKey = (d.thesis === `evidence` && d.ask === `runway` && d.probe === `own`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // ---- Apply evidence & fit deltas (clamped 0-100). ----
            ds.evidence = Math.max(0, Math.min(100, Math.round(ds.evidence + evidenceDelta)));
            ds.fit = Math.max(0, Math.min(100, Math.round(ds.fit + fitDelta)));

            // ---- Cash & runway: base burn + experiment spend + delay burn each round. ----
            const monthBurn = this.MONTHLY_BURN + spendThisRound + delayBurn;
            ds.cash = Math.max(0, Math.round(ds.cash - monthBurn));
            ds.runway = Math.round((ds.cash / this.MONTHLY_BURN) * 10) / 10;

            // ---- End of Round 4: the grant tranche test + the angel's SAFE. ----
            let grantBooked = false;
            if (round === 4) {
                // Grant agency accepts the evidence only if it is genuinely validated.
                if (ds.evidence >= this.EVIDENCE_TRANCHE_GATE && !ds.vanityTrap && !ds.parallelTrap) {
                    ds.cash += this.GRANT_TRANCHE;                     // CHF 60,000 tranche unlocked
                    ds.runway = Math.round((ds.cash / this.MONTHLY_BURN) * 10) / 10;
                    grantBooked = true;
                    ds.trancheLost = false;
                } else {
                    ds.trancheLost = true;                             // collapse scenario (<2 months)
                }

                // The angel's SAFE: conditional on fit AND real validation signal AND a decided company.
                ds.safeSecured = (
                    ds.fit >= this.FIT_ANGEL_GATE &&
                    ds.evidence >= this.EVIDENCE_ANGEL_GATE &&
                    !ds.passionTrap && !ds.vanityTrap && !ds.parallelTrap && !ds.pivotDenial &&
                    !ds.trancheLost &&
                    ds.delayMonths < 1 &&
                    d.thesis === `evidence`
                );
                if (ds.safeSecured) {
                    ds.cash += this.SAFE_OFFER;
                    ds.runway = Math.round((ds.cash / this.MONTHLY_BURN) * 10) / 10;
                }
            }

            ds.runwayHistory.push(ds.runway);
            ds.evidenceHistory.push(ds.evidence);
            ds.fitHistory.push(ds.fit);

            // ---- Persist composite where the grading/reporting layer reads it ----
            const _score = this._composite(ds);
            ds.score = _score;
            ds.performance = ds.performance || {};
            ds.performance.overallScore = _score;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                overallScore: _score,
                score: _score,
                cash: ds.cash,
                runway: ds.runway,
                evidence: ds.evidence,
                evidenceDelta: Math.round(evidenceDelta),
                fit: ds.fit,
                fitDelta: Math.round(fitDelta),
                committed: ds.committed,
                committedLabel: this._oppLabel(ds.committed),
                spendThisRound: spendThisRound,
                delayBurn: delayBurn,
                grantBooked: grantBooked,
                trancheLost: ds.trancheLost,
                safeSecured: ds.safeSecured,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _oppLabel(code) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            if (code === `a`) return t(`opp_a_short`);
            if (code === `b`) return t(`opp_b_short`);
            if (code === `c`) return t(`opp_c_short`);
            return `—`;
        }

        _fmtCHF(v) {
            // CHF with apostrophe thousands separator, Swiss style.
            const n = Math.round(Number(v));
            const s = Math.abs(n).toString().replace(/\B(?=(\d{3})+(?!\d))/g, `’`);
            return `CHF ${n < 0 ? `-` : ``}${s}`;
        }

        _fmtRunway(v) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = (Math.round(Number(v) * 10) / 10).toFixed(1);
            const num = lang === `es` ? s.replace(`.`, `,`) : s;
            return `${num} ${window.mySimulation.t(`mo_suffix`)}`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`runwayDisplay`, `domainState.runway`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.scoutsim-card-runway`);
                if (card) {
                    card.classList.toggle(`scoutsim-runway-danger`, n < 2);
                    card.classList.toggle(`scoutsim-runway-warn`, n >= 2 && n < 4);
                    card.classList.toggle(`scoutsim-runway-good`, n >= 4);
                }
                return self._fmtRunway(n);
            });

            uiManager.bind(`cashDisplay`, `domainState.cash`, (v) => self._fmtCHF(v));

            uiManager.bind(`evidenceDisplay`, `domainState.evidence`, (v) => {
                const n = Math.round(Number(v));
                const card = document.querySelector(`.scoutsim-card-evidence`);
                if (card) {
                    card.classList.toggle(`scoutsim-evidence-good`, n >= self.EVIDENCE_ANGEL_GATE);
                    card.classList.toggle(`scoutsim-evidence-weak`, n < self.EVIDENCE_TRANCHE_GATE);
                }
                return `${n}`;
            });

            uiManager.bind(`fitDisplay`, `domainState.fit`, (v) => {
                const n = Math.round(Number(v));
                const card = document.querySelector(`.scoutsim-card-fit`);
                if (card) {
                    card.classList.toggle(`scoutsim-fit-good`, n >= self.FIT_ANGEL_GATE);
                    card.classList.toggle(`scoutsim-fit-weak`, n < 45);
                }
                return `${n}`;
            });

            uiManager.bind(`creditsDisplay`, `domainState.credits`, (v) => `${Math.round(Number(v))}`);
            uiManager.bind(`budgetDisplay`, `domainState.budget`, (v) => self._fmtCHF(v));
            uiManager.bind(`committedDisplay`, `domainState.committed`, (v) => self._oppLabel(v));

            // Discipline slider readout.
            const di = document.getElementById(`discInput`);
            const diReadout = document.getElementById(`discReadout`);
            if (di && diReadout) {
                diReadout.textContent = di.value;
                di.addEventListener(`input`, function() { diReadout.textContent = di.value; });
            }
        }

        getChartConfig() {
            return {
                scoutTrajectoryChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(`chart_series_evidence`) : `Validation evidence (0–100)`,
                                data: [],
                                borderColor: `#16a085`,
                                backgroundColor: `rgba(22,160,133,0.12)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#16a085`,
                                yAxisID: `y`
                            },
                            {
                                label: (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(`chart_series_fit`) : `Opportunity-fit score (0–100)`,
                                data: [],
                                borderColor: `#6c5ce0`,
                                backgroundColor: `rgba(108,92,224,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#6c5ce0`,
                                yAxisID: `y`
                            },
                            {
                                label: (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(`chart_series_runway`) : `Runway (months × 10)`,
                                data: [],
                                borderColor: `#0f5d7a`,
                                backgroundColor: `rgba(15,93,122,0.08)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#0f5d7a`,
                                yAxisID: `y`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#46506a`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true, max: 100, position: `left`,
                                ticks: { color: `#7a8398` }, grid: { color: `rgba(26,35,48,0.06)` },
                                title: { display: true, text: `0–100`, color: `#7a8398` }
                            },
                            x: {
                                ticks: { color: `#7a8398` }, grid: { color: `rgba(26,35,48,0.04)` },
                                title: { display: true, text: `Round`, color: `#7a8398` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.evidenceHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            // Runway months are 0–~12+; scale ×10 to share the 0–100 axis (capped at 100).
            const runwayScaled = ds.runwayHistory.map((v) => Math.min(100, Math.round(v * 10)));
            return {
                scoutTrajectoryChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.evidenceHistory.map((v) => Math.round(v)) },
                        { data: ds.fitHistory.map((v) => Math.round(v)) },
                        { data: runwayScaled }
                    ]
                }
            };
        }

        _composite(ds) {
            // v1.0.0 completion formula, single source of truth, persisted every period so the
            // grading/analytics/LTI layer (domainState.performance.overallScore then top-level
            // score) receives a number instead of null -> 0.0.
            const evidence = Math.round(ds.evidence);
            const fit = Math.round(ds.fit);
            const runway = Math.round(ds.runway * 10) / 10;
            const runwayScore = Math.min(100, (runway / 6) * 100);
            return Math.round(evidence * 0.34 + fit * 0.34 + runwayScore * 0.32);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const evidence = Math.round(ds.evidence);
            const fit = Math.round(ds.fit);
            const runway = Math.round(ds.runway * 10) / 10;
            const cash = Math.round(ds.cash);

            // Composite blends the three KPIs; runway is capped at the 6-month line for scoring.
            const composite = this._composite(ds);

            // Decision delay is the fifth classic Common Error and a run-defining choice:
            // a full month of indecision must gate the top verdicts exactly as the four sticky traps do.
            const delayed = ds.delayMonths >= 1;
            const anyTrap = ds.passionTrap || ds.vanityTrap || ds.parallelTrap || ds.pivotDenial || delayed;
            const evidenceStrong = evidence >= this.EVIDENCE_ANGEL_GATE;
            const fitStrong = fit >= this.FIT_ANGEL_GATE;
            const solvent = runway >= 2 && !ds.trancheLost;

            let pattern = `mixed`;
            if (ds.safeSecured) pattern = `investable`;
            else if (ds.pivotDenial) pattern = `denial`;
            else if (ds.passionTrap) pattern = `passion`;
            else if (ds.vanityTrap) pattern = `vanity`;
            else if (ds.parallelTrap) pattern = `parallel`;
            else if (delayed) pattern = `delay`;
            else if (ds.trancheLost || runway < 2) pattern = `runway`;

            let performance = `Runway Burned`, performanceKey = `grade_burned`;
            if (ds.safeSecured && composite >= 72) { performance = `Investable — SAFE Secured`; performanceKey = `grade_investable`; }
            else if (evidenceStrong && fitStrong && solvent && !anyTrap) { performance = `Validated & Funded-Ready`; performanceKey = `grade_validated`; }
            else if (solvent && !anyTrap && composite >= 55) { performance = `Disciplined but Short`; performanceKey = `grade_disciplined`; }
            else if (ds.pivotDenial) { performance = `Pivot Denial`; performanceKey = `grade_denial`; }
            else if (ds.passionTrap) { performance = `Passion over Score`; performanceKey = `grade_passion`; }
            else if (ds.vanityTrap) { performance = `Vanity Validation`; performanceKey = `grade_vanity`; }
            else if (ds.parallelTrap) { performance = `Parallel Paralysis`; performanceKey = `grade_parallel`; }
            else if (delayed) { performance = `Decision Delayed`; performanceKey = `grade_delayed`; }
            else if (ds.trancheLost || runway < 2) { performance = `Runway Burned`; performanceKey = `grade_burned`; }

            const insights = [];
            if (pattern === `investable`) insights.push(window.mySimulation.t(`insight_investable`));
            else if (pattern === `denial`) insights.push(window.mySimulation.t(`insight_denial`));
            else if (pattern === `passion`) insights.push(window.mySimulation.t(`insight_passion`));
            else if (pattern === `vanity`) insights.push(window.mySimulation.t(`insight_vanity`));
            else if (pattern === `parallel`) insights.push(window.mySimulation.t(`insight_parallel`));
            else if (pattern === `delay`) insights.push(window.mySimulation.t(`insight_delay`));
            else if (pattern === `runway`) insights.push(window.mySimulation.t(`insight_runway`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (ds.trancheLost) insights.push(window.mySimulation.t(`insight_tranche`));
            if (ds.delayMonths >= 1 && pattern !== `delay`) insights.push(window.mySimulation.t(`insight_delay`));
            if (evidence < this.EVIDENCE_TRANCHE_GATE) insights.push(window.mySimulation.t(`insight_evidence_low`));
            if (fit < 45) insights.push(window.mySimulation.t(`insight_fit_low`));
            if (evidenceStrong && fitStrong && runway < 2) insights.push(window.mySimulation.t(`insight_won_but_broke`));

            return {
                evidence: evidence,
                fit: fit,
                runway: runway,
                cash: cash,
                evidenceStrong: evidenceStrong,
                fitStrong: fitStrong,
                solvent: solvent,
                safeSecured: ds.safeSecured,
                trancheLost: ds.trancheLost,
                delayMonths: Math.round(ds.delayMonths * 100) / 100,
                committed: this._oppLabel(ds.committed),
                pattern: pattern,
                composite: composite,
                performance: performance,
                performanceKey: performanceKey,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const self = this;
            const t = (window.mySimulation && window.mySimulation.t)
                ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            if (!summary || typeof summary.composite !== `number`) {
                return `<div class="scoutsim-cm"><p class="scoutsim-cm-generic">${t(`cm_generic`)}</p></div>`;
            }
            const tier = summary.performanceKey ? t(summary.performanceKey) : (summary.performance || ``);
            const kpi = (labelKey, valStr) =>
                `<div class="scoutsim-cm-kpi"><span class="scoutsim-cm-kpi-val">${valStr}</span>`
                + `<span class="scoutsim-cm-kpi-lbl">${t(labelKey)}</span></div>`;
            const chip = (ok, labelKey) =>
                `<span class="scoutsim-cm-chip ${ok ? `is-met` : `is-missed`}">`
                + `${ok ? `✓` : `✗`} ${t(labelKey)}</span>`;
            const insights = (summary.insights || []).map((x) => `<li>${x}</li>`).join(``);
            return ``
                + `<div class="scoutsim-cm">`
                +   `<div class="scoutsim-cm-scoreband">`
                +     `<div class="scoutsim-cm-score">${summary.composite}<span class="scoutsim-cm-score-max">/100</span></div>`
                +     `<div class="scoutsim-cm-tier">${tier}</div>`
                +     `<div class="scoutsim-cm-caption">${t(`cm_caption`)}</div>`
                +   `</div>`
                +   `<div class="scoutsim-cm-kpis">`
                +     kpi(`cm_kpi_evidence`, String(Math.round(summary.evidence)))
                +     kpi(`cm_kpi_fit`, String(Math.round(summary.fit)))
                +     kpi(`cm_kpi_runway`, self._fmtRunway(summary.runway))
                +     kpi(`cm_kpi_cash`, self._fmtCHF(summary.cash))
                +   `</div>`
                +   `<div class="scoutsim-cm-chips">`
                +     chip(summary.evidenceStrong, `cm_chip_evidence`)
                +     chip(summary.fitStrong, `cm_chip_fit`)
                +     chip(summary.solvent, `cm_chip_solvent`)
                +     chip(summary.safeSecured, `cm_chip_safe`)
                +   `</div>`
                +   (insights ? `<ul class="scoutsim-cm-insights">${insights}</ul>` : ``)
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.runway < 2) return window.mySimulation.t(`hint_runway`);
            if (ds.pivotDenial) return window.mySimulation.t(`hint_denial`);
            if (ds.passionTrap && ds.fit < 45) return window.mySimulation.t(`hint_passion`);
            if (ds.vanityTrap) return window.mySimulation.t(`hint_vanity`);
            if (ds.parallelTrap) return window.mySimulation.t(`hint_parallel`);
            if (ds.delayMonths >= 1) return window.mySimulation.t(`hint_delay`);
            if (ds.evidence < this.EVIDENCE_TRANCHE_GATE && state.currentPeriod >= 3) return window.mySimulation.t(`hint_evidence`);
            if (ds.fit >= this.FIT_ANGEL_GATE && ds.evidence >= this.EVIDENCE_ANGEL_GATE) return window.mySimulation.t(`hint_strong`);
            return null;
        }

